import { useCallback, useMemo } from 'react'
import { Token } from '@uniswap/sdk-core'

import { GqlResult } from 'uniswap/src/data/types'
import { SafetyLevel, ProtectionResult } from 'uniswap/src/data/graphql/uniswap-data-api/__generated__/types-and-hooks'
import { useEnabledChains } from 'uniswap/src/features/chains/hooks/useEnabledChains'
import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { CurrencyInfo } from 'uniswap/src/features/dataApi/types'
import { getCurrencySafetyInfo } from 'uniswap/src/features/dataApi/utils'
import { getAbstractTokenList } from 'uniswap/src/constants/tokens'
import { getTokenLogoUrl } from 'uniswap/src/constants/tokenLogos'
import { currencyId } from 'uniswap/src/utils/currencyId'
import { isAddress } from 'utilities/src/addresses'

// Convert Token to CurrencyInfo format
function tokenToCurrencyInfo(token: Token): CurrencyInfo {
  // All our hardcoded Abstract tokens are verified/safe
  const safetyInfo = getCurrencySafetyInfo(SafetyLevel.Verified, {
    attackTypes: [],
    result: ProtectionResult.Benign,
  })

  return {
    currencyId: currencyId(token),
    currency: token,
    logoUrl: getTokenLogoUrl(token.address),
    safetyLevel: SafetyLevel.Verified,
    safetyInfo,
    isSpam: false,
  }
}

export function useSearchTokensGql(
  searchQuery: string | null,
  chainFilter: UniverseChainId | null,
  skip: boolean,
): GqlResult<CurrencyInfo[]> {
  const { chains } = useEnabledChains()

  const isSearchQueryAnAddress = isAddress(searchQuery)

  const formattedData = useMemo(() => {
    if (skip || !searchQuery) {
      return undefined
    }

    const query = searchQuery.toLowerCase()
    const results: CurrencyInfo[] = []

    // Get tokens for all enabled chains or just the filtered chain
    const chainsToSearch = chainFilter ? [chainFilter] : chains

    chainsToSearch.forEach((chainId) => {
      const chainTokens = getAbstractTokenList(chainId)
      
      const matchingTokens = chainTokens.filter((token) => {
        // If searching by address, match exact address
        if (isSearchQueryAnAddress) {
          return token.address.toLowerCase() === query
        }
        
        // Otherwise, search by symbol or name
        return (
          token.symbol?.toLowerCase().includes(query) ||
          token.name?.toLowerCase().includes(query)
        )
      })

      // Convert to CurrencyInfo format
      const currencyInfos = matchingTokens.map((token) => ({
        ...tokenToCurrencyInfo(token),
        isFromOtherNetwork: chainFilter ? chainId !== chainFilter : false,
      }))

      results.push(...currencyInfos)
    })

    // Sort results: exact symbol matches first, then partial matches
    return results.sort((a, b) => {
      const aSymbol = a.currency?.symbol?.toLowerCase() || ''
      const bSymbol = b.currency?.symbol?.toLowerCase() || ''
      
      const aExactMatch = aSymbol === query
      const bExactMatch = bSymbol === query
      
      if (aExactMatch && !bExactMatch) return -1
      if (!aExactMatch && bExactMatch) return 1
      
      return aSymbol.localeCompare(bSymbol)
    })
  }, [searchQuery, chainFilter, chains, skip, isSearchQueryAnAddress])

  const retry = useCallback(() => {
    // No-op for local search since there's no network request to retry
  }, [])

  return useMemo(
    () => ({ 
      data: formattedData, 
      loading: false, 
      error: undefined, 
      refetch: retry 
    }),
    [formattedData, retry],
  )
}
