"use strict";
import { Flex, styled } from "ui/src";
const StarBorderBottom = styled(Flex, {
  position: "absolute",
  width: "300%",
  height: "50%",
  opacity: 0.7,
  bottom: -12,
  right: "-250%",
  borderRadius: "$roundedFull",
  zIndex: 0
});
const StarBorderTop = styled(StarBorderBottom, {
  top: -12,
  left: "-250%",
  bottom: "unset",
  right: "unset"
});
export const StarBorderButton = ({
  as: Component = "button",
  className = "",
  color = "white",
  speed = "5s",
  py = 12,
  px = 16,
  borderRadius = 32,
  disabled = false,
  children,
  style,
  ...rest
}) => {
  return <Component
    className={`${className}`}
    style={{
      padding: "1px 0",
      display: "inline-block",
      overflow: "hidden",
      position: "relative",
      borderRadius: borderRadius - borderRadius / 2,
      // minus 50%
      ...style,
      cursor: disabled ? "not-allowed" : "pointer"
    }}
  >
      <StarBorderBottom
    className="border-gradient-bottom"
    style={{
      background: `radial-gradient(circle, ${color}, transparent 10%)`,
      animationDuration: speed,
      display: disabled ? "none" : "block"
    }}
  />
      <StarBorderTop
    className="border-gradient-top"
    style={{
      background: `radial-gradient(circle, ${color}, transparent 10%)`,
      animationDuration: speed,
      display: disabled ? "none" : "block"
    }}
  />
      <Flex
    disabled={disabled}
    py={py}
    px={px}
    borderWidth={2}
    borderColor={"$surface3"}
    borderRadius={borderRadius}
    backgroundColor={"$surface1"}
    opacity={disabled ? 0.5 : 1}
    position="relative"
    zIndex={1}
    transition="all 0.2s ease-in-out"
    hoverStyle={{
      borderColor: disabled ? "$surface3Hovered" : "$surface3",
      backgroundColor: disabled ? "$surface1" : "$slate"
    }}
    {...rest}
  >
        {children}
      </Flex>
    </Component>;
};
