import { TradeType } from '@uniswap/sdk-core'
import { UseTradeArgs } from 'uniswap/src/features/transactions/swap/types/trade'
import { areCurrencyIdsEqual, currencyId } from 'uniswap/src/utils/currencyId'
import { useAbstractQuote } from 'uniswap/src/features/routing/hooks/useAbstractQuote'
import { ClassicTrade } from 'state/routing/types'

export function useTrade({
  amountSpecified: amount,
  otherCurrency,
  tradeType,
  skip,
  isDebouncing,
}: UseTradeArgs): { trade: ClassicTrade | null; isLoading: boolean; error: Error | null } {
  /***** Format request arguments ******/

  const currencyIn = tradeType === TradeType.EXACT_INPUT ? amount?.currency : otherCurrency
  const currencyOut = tradeType === TradeType.EXACT_OUTPUT ? amount?.currency : otherCurrency
  const currencyInEqualsCurrencyOut =
    currencyIn && currencyOut && areCurrencyIdsEqual(currencyId(currencyIn), currencyId(currencyOut))

  const isZeroAmount = amount?.quotient.toString() === '0'

  // Skip conditions for Abstract DEX
  const abstractSkip =
    skip ||
    !amount ||
    isZeroAmount ||
    currencyInEqualsCurrencyOut ||
    !currencyIn ||
    !currencyOut

  // Always use Abstract DEX quotes
  const abstractTokenIn = currencyIn?.isNative ? currencyIn.wrapped.address : currencyIn?.address
  const abstractTokenOut = currencyOut?.isNative ? currencyOut.wrapped.address : currencyOut?.address
  const abstractAmount = amount?.quotient.toString()

  return useAbstractQuote({
    tokenIn: abstractTokenIn,
    tokenOut: abstractTokenOut,
    amountSpecified: abstractAmount,
    tradeType,
    chainId: currencyIn?.chainId,
    skip: abstractSkip,
  })
}
