// Helper to convert formatted reserve to raw amount for Pair creation
function parseReserveToRaw(reserve: string, decimals: number): string {
  // Subgraph returns formatted amounts (e.g. "33843.701"), convert to raw wei
  // Handle scientific notation (e.g., "1.234e+21")
  if (reserve.includes('e') || reserve.includes('E')) {
    try {
      const num = parseFloat(reserve)
      if (!isFinite(num) || num < 0) {
        console.warn('Invalid scientific notation reserve:', reserve)
        return '0'
      }
      // Convert to fixed decimal string to avoid precision loss
      const fixedStr = num.toFixed(decimals)
      return parseReserveToRaw(fixedStr, decimals)
    } catch (error) {
      console.warn('Failed to parse scientific notation:', reserve, error)
      return '0'
    }
  }
  
  // Use string manipulation to avoid scientific notation issues with large numbers
  const parts = reserve.split('.')
  const wholePart = parts[0] || '0'
  const fractionalPart = parts[1] || ''

  // Calculate how many decimal places we need to shift
  const fractionalDigits = fractionalPart.length
  const zerosToAdd = Math.max(0, decimals - fractionalDigits)

  // Construct the raw amount as a string
  const rawAmount = wholePart + fractionalPart + '0'.repeat(zerosToAdd)

  // Remove leading zeros but keep at least one digit
  return rawAmount.replace(/^0+/, '') || '0'
}

// V2 Quote Logic
export async function getV2Quote(params: V2QuoteParams): Promise<V2Trade<Currency, Currency, TradeType> | null> {
  const { currencyIn, currencyOut, inputAmount, amountSpecified, tradeType, poolData, effectiveChainId } = params
  
  
  try {
    // Filter relevant pools and create Pair objects
    const tokenInAddress = currencyIn.isToken ? currencyIn.address.toLowerCase() : currencyIn.wrapped.address.toLowerCase()
    const tokenOutAddress = currencyOut.isToken ? currencyOut.address.toLowerCase() : currencyOut.wrapped.address.toLowerCase()
    
    const relevantV2Pools = poolData.filter(pool => {
      const hasTokenIn = pool.token0.id.toLowerCase() === tokenInAddress || pool.token1.id.toLowerCase() === tokenInAddress
      const hasTokenOut = pool.token0.id.toLowerCase() === tokenOutAddress || pool.token1.id.toLowerCase() === tokenOutAddress
      const isDirectPair = hasTokenIn && hasTokenOut
      const isRelevantForRouting = hasTokenIn || hasTokenOut
      
      
      // Best practice liquidity filtering based on common DEX implementations
      // CRITICAL FIX: Apply filtering to ALL pools used for routing, not just direct pairs
      // This prevents toxic intermediate pools from being used in multi-hop routes
      
      // For filtering, we need to determine which token pair we're potentially trading
      let shouldApplyFiltering = false
      let inputReserve, outputReserve, inputAmountFormatted, tokenInSymbol, tokenOutSymbol
      
      if (isDirectPair) {
        // Direct pair: apply strict filtering with actual trade amounts
        shouldApplyFiltering = true
        const tokenOutIsToken0 = pool.token0.id.toLowerCase() === tokenOutAddress
        outputReserve = parseFloat(tokenOutIsToken0 ? pool.reserve0 : pool.reserve1)
        inputReserve = parseFloat(tokenOutIsToken0 ? pool.reserve1 : pool.reserve0)
        // Fix decimal formatting to use correct decimals instead of assuming 18
        inputAmountFormatted = parseFloat(ethers.utils.formatUnits(inputAmount.quotient.toString(), currencyIn.decimals))
        tokenInSymbol = tokenOutIsToken0 ? pool.token1.symbol : pool.token0.symbol
        tokenOutSymbol = tokenOutIsToken0 ? pool.token0.symbol : pool.token1.symbol
      } else {
        // Intermediate pair: apply basic liquidity filtering
        const hasInputToken = pool.token0.id.toLowerCase() === tokenInAddress || pool.token1.id.toLowerCase() === tokenInAddress
        const hasOutputToken = pool.token0.id.toLowerCase() === tokenOutAddress || pool.token1.id.toLowerCase() === tokenOutAddress
        
        if (hasInputToken) {
          // This pool contains our input token, first hop: InputToken -> IntermediateToken
          shouldApplyFiltering = true
          const tokenInIsToken0 = pool.token0.id.toLowerCase() === tokenInAddress
          inputReserve = parseFloat(tokenInIsToken0 ? pool.reserve0 : pool.reserve1)
          outputReserve = parseFloat(tokenInIsToken0 ? pool.reserve1 : pool.reserve0)
          // Fix decimal formatting to use correct decimals instead of assuming 18
        inputAmountFormatted = parseFloat(ethers.utils.formatUnits(inputAmount.quotient.toString(), currencyIn.decimals))
          tokenInSymbol = tokenInIsToken0 ? pool.token0.symbol : pool.token1.symbol
          tokenOutSymbol = tokenInIsToken0 ? pool.token1.symbol : pool.token0.symbol
        } else if (hasOutputToken) {
          // This pool contains our output token, second hop: IntermediateToken -> OutputToken
          shouldApplyFiltering = true
          const tokenOutIsToken0 = pool.token0.id.toLowerCase() === tokenOutAddress
          outputReserve = parseFloat(tokenOutIsToken0 ? pool.reserve0 : pool.reserve1)
          inputReserve = parseFloat(tokenOutIsToken0 ? pool.reserve1 : pool.reserve0)
          // For second hop, use conservative estimate of trade amount
          inputAmountFormatted = parseFloat(ethers.utils.formatUnits(inputAmount.quotient.toString(), currencyIn.decimals)) * 0.5
          tokenInSymbol = tokenOutIsToken0 ? pool.token1.symbol : pool.token0.symbol
          tokenOutSymbol = tokenOutIsToken0 ? pool.token0.symbol : pool.token1.symbol
        }
      }

      if (shouldApplyFiltering) {
        // Calculate price impact for this potential hop
        const priceImpactPercent = (inputAmountFormatted / (inputReserve + inputAmountFormatted)) * 100
        
        // Calculate expected output
        const expectedOutput = (outputReserve * inputAmountFormatted) / (inputReserve + inputAmountFormatted)
        
        // 1. Price Impact Protection
        // Different logic for stable vs volatile pools
        const isStablePool = pool.stable === true
        
        if (isStablePool) {
          // Stable pools should maintain 1:1 ratios - moderate filtering (following Curve practices)
          const STABLE_MAX_PRICE_IMPACT = isDirectPair ? 5 : 2  // 5% max for direct stable pairs, 2% for intermediate
          
          if (priceImpactPercent > STABLE_MAX_PRICE_IMPACT) {
            return false
          }
        } else {
          // Volatile pools - no hard price impact limit for direct pairs
          // Only filter intermediate pools with extreme price impact to prevent toxic routing
          if (!isDirectPair && priceImpactPercent > 25) {  // 25% max for intermediate volatile pools only
            return false
          }
        }
        
        // 2. Removed liquidity protection - let users see actual available trades
        // Price impact calculation already shows users the real cost
        
        // 3. Minimum Input Reserve Check (apply to ALL pools)
        const MIN_INPUT_RESERVE_RATIO = 0.01
        if (inputReserve > 0 && inputAmountFormatted / inputReserve > 1 / MIN_INPUT_RESERVE_RATIO) {
          return false
        }
        
        // 4. Additional check for intermediate pools: Minimum absolute reserve requirements
        if (!isDirectPair) {
          const MIN_ABSOLUTE_RESERVE = 10 // At least $10 worth of reserves for intermediate pools
          if (inputReserve < MIN_ABSOLUTE_RESERVE || outputReserve < MIN_ABSOLUTE_RESERVE) {
            return false  
          }
        }
        
      }
      
      return isRelevantForRouting
    })


    
    if (relevantV2Pools.length === 0) {
      return null
    }

    // Create Pair objects from pool data
    const pairs: Pair[] = []
    
    for (const poolData of relevantV2Pools) {
      try {
        const token0 = new Token(
          effectiveChainId,
          poolData.token0.id,
          parseInt(poolData.token0.decimals),
          poolData.token0.symbol,
          poolData.token0.name
        )
        const token1 = new Token(
          effectiveChainId,
          poolData.token1.id,
          parseInt(poolData.token1.decimals),
          poolData.token1.symbol,
          poolData.token1.name
        )

        // Convert formatted reserves to raw amounts
        const reserve0Raw = parseReserveToRaw(poolData.reserve0, token0.decimals)
        const reserve1Raw = parseReserveToRaw(poolData.reserve1, token1.decimals)
        
        // Skip pools with zero liquidity
        if (reserve0Raw === '0' || reserve1Raw === '0') {
          console.log(`Skipping zero liquidity pool: ${poolData.id}`)
          continue
        }

        // Create pair with correct Abstract DEX pool address (not computed via CREATE2)
        const currencyAmount0 = CurrencyAmount.fromRawAmount(token0, reserve0Raw)
        const currencyAmount1 = CurrencyAmount.fromRawAmount(token1, reserve1Raw)
        
        const pair = new Pair(currencyAmount0, currencyAmount1)
        const computedAddress = pair.liquidityToken.address
        const actualPoolAddress = poolData.id // This is the real pool address from subgraph
        
        
        // Store the real pool address and stable flag for later use
        ;(pair as any).actualAddress = actualPoolAddress
        ;(pair as any).stable = poolData.stable

        pairs.push(pair)
      } catch (pairError) {
        // Skip failed pairs
      }
    }

    
    if (pairs.length === 0) {
      return null
    }

    // Get trade using V2Trade SDK
    if (tradeType === TradeType.EXACT_INPUT) {
      const trades = V2Trade.bestTradeExactIn(pairs, inputAmount, currencyOut, {
        maxHops: 2,
        maxNumResults: 1,
      })
      
      if (trades.length > 0) {
        return trades[0]
      } else {
        return null
      }
    } else {
      const outputAmount = CurrencyAmount.fromRawAmount(currencyOut, amountSpecified)
      const trades = V2Trade.bestTradeExactOut(pairs, currencyIn, outputAmount, {
        maxHops: 2,
        maxNumResults: 1,
      })
      
      if (trades.length > 0) {
        return trades[0]
      } else {
        return null
      }
    }
  } catch (error) {
    console.error('V2 quote error:', error)
    return null
  }
}

// Simple in-memory cache for V3 quotes
const v3QuoteCache = new Map<string, { result: V3Quote | null; timestamp: number }>()
const CACHE_TTL_MS = 15000 // 15 seconds

// Helper to create exact cache key (no rounding)
function createV3CacheKey(params: V3QuoteParams): string {
  return `${params.tokenIn.toLowerCase()}-${params.tokenOut.toLowerCase()}-${params.amountSpecified}-${params.tradeType}`
}

// Helper to clean expired cache entries
function cleanExpiredCache() {
  const now = Date.now()
  for (const [key, entry] of v3QuoteCache.entries()) {
    if (now - entry.timestamp > CACHE_TTL_MS) {
      v3QuoteCache.delete(key)
    }
  }
}

// V3 Quote Logic
export async function getV3Quote(params: V3QuoteParams): Promise<V3Quote | null> {
  const { tokenIn, tokenOut, inputAmount, amountSpecified, tradeType, v3Pools, quoterContract, multicallContract } = params
  
  // Check cache first
  const cacheKey = createV3CacheKey(params)
  cleanExpiredCache()
  
  const cached = v3QuoteCache.get(cacheKey)
  if (cached && (Date.now() - cached.timestamp) < CACHE_TTL_MS) {
    console.log('V3 quote cache hit for:', amountSpecified)
    return cached.result
  }
  
  try {
    // Filter to direct pools for this token pair
    const tokenInLower = tokenIn.toLowerCase()
    const tokenOutLower = tokenOut.toLowerCase()
    
    const directV3Pools = v3Pools.filter(pool => {
      const token0Lower = pool.token0.id.toLowerCase()
      const token1Lower = pool.token1.id.toLowerCase()
      return (token0Lower === tokenInLower && token1Lower === tokenOutLower) ||
             (token0Lower === tokenOutLower && token1Lower === tokenInLower)
    })
    
    
    if (directV3Pools.length === 0) {
      // Cache null result for no pools found
      v3QuoteCache.set(cacheKey, { result: null, timestamp: Date.now() })
      return null
    }
    
    const availableTickSpacings = [...new Set(directV3Pools.map(pool => pool.tickSpacing))]
    
    const tickSpacingToFee: { [key: string]: number } = {
      '1': 100, '50': 500, '100': 500, '200': 3000, '2000': 10000
    }
    
    // Prepare multicall for all tick spacings
    const calls = availableTickSpacings.map(tickSpacing => {
      let callData
      
      if (tradeType === TradeType.EXACT_INPUT) {
        callData = quoterContract.interface.encodeFunctionData('quoteExactInputSingle', [{
          tokenIn: tokenIn,
          tokenOut: tokenOut,
          amountIn: inputAmount.quotient.toString(),
          tickSpacing: parseInt(tickSpacing),
          sqrtPriceLimitX96: 0
        }])
      } else {
        // For EXACT_OUTPUT, use the amount as specified
        callData = quoterContract.interface.encodeFunctionData('quoteExactOutputSingle', [{
          tokenIn: tokenIn,
          tokenOut: tokenOut,
          amountOut: inputAmount.quotient.toString(),
          tickSpacing: parseInt(tickSpacing),
          sqrtPriceLimitX96: 0
        }])
      }
      
      return {
        target: quoterContract.address,
        callData
      }
    })
    
    // Execute multicall with timeout protection
    
    let result
    try {
      // Add timeout protection
      const timeoutPromise = new Promise((_, reject) => 
        setTimeout(() => reject(new Error('Multicall timeout after 30 seconds')), 30000)
      )
      
      const multicallPromise = multicallContract.callStatic.tryAggregate(false, calls)
      
      result = await Promise.race([multicallPromise, timeoutPromise])
    } catch (multicallError) {
      console.error('V3 multicall failed:', multicallError)
      return null
    }
    
    // Process results - tryAggregate returns array of {success: boolean, returnData: bytes}
    const quoteResults = result.map((callResult: any, i: number) => {
      const tickSpacing = availableTickSpacings[i]
      const fee = tickSpacingToFee[tickSpacing]
      
      // Skip unknown tick spacings
      if (!fee) {
        console.warn(`Unknown tick spacing: ${tickSpacing}, skipping`)
        return null
      }
      
      // Skip failed calls
      if (!callResult.success) {
        return null
      }
      
      try {
        let decoded
        if (tradeType === TradeType.EXACT_INPUT) {
          decoded = quoterContract.interface.decodeFunctionResult('quoteExactInputSingle', callResult.returnData)
        } else {
          decoded = quoterContract.interface.decodeFunctionResult('quoteExactOutputSingle', callResult.returnData)
        }
        
        return { result: decoded, fee, tickSpacing }
      } catch (decodeError) {
        return null
      }
    })
    
    // Find best quote
    let bestQuoteResult: any = null
    let bestFee = 0
    let bestTickSpacing = 0
    
    for (const quoteData of quoteResults) {
      if (quoteData) {
        if (tradeType === TradeType.EXACT_INPUT) {
          // For exact input, pick the quote with highest output
          if (!bestQuoteResult || quoteData.result.amountOut.gt(bestQuoteResult.amountOut)) {
            bestQuoteResult = quoteData.result
            bestFee = quoteData.fee
            bestTickSpacing = parseInt(quoteData.tickSpacing)
          }
        } else {
          // For exact output, pick the quote with lowest input required
          if (!bestQuoteResult || quoteData.result.amountIn.lt(bestQuoteResult.amountIn)) {
            bestQuoteResult = quoteData.result
            bestFee = quoteData.fee
            bestTickSpacing = parseInt(quoteData.tickSpacing)
          }
        }
      }
    }
    
    if (!bestQuoteResult) {
      // Cache null result too
      v3QuoteCache.set(cacheKey, { result: null, timestamp: Date.now() })
      return null
    }
    
    // Create quote object
    let quoteResult: V3Quote | null
    if (tradeType === TradeType.EXACT_INPUT) {
      quoteResult = {
        amountOut: bestQuoteResult.amountOut.toString(),
        fee: bestFee,
        tickSpacing: bestTickSpacing,
        tokenIn: params.currencyIn,
        tokenOut: params.currencyOut,
        amountIn: inputAmount.quotient.toString(),
        gasEstimate: bestQuoteResult.gasEstimate?.toString() || '200000',
      }
    } else {
      quoteResult = {
        amountOut: inputAmount.quotient.toString(),
        fee: bestFee,
        tickSpacing: bestTickSpacing,
        tokenIn: params.currencyIn,
        tokenOut: params.currencyOut,
        amountIn: bestQuoteResult.amountIn.toString(),
        gasEstimate: bestQuoteResult.gasEstimate?.toString() || '200000',
      }
    }
    
    // Cache the successful result
    v3QuoteCache.set(cacheKey, { result: quoteResult, timestamp: Date.now() })
    return quoteResult
    
  } catch (error) {
    console.error('V3 quote error:', error)
    // Cache null result for errors too (shorter TTL)
    v3QuoteCache.set(cacheKey, { result: null, timestamp: Date.now() })
    return null
  }
}

// Trade Comparison Logic
export function compareTrades(
  v2Trade: V2Trade<Currency, Currency, TradeType> | null,
  v3Quote: V3Quote | null,
  tradeType: TradeType,
  currencyIn: Currency,
  currencyOut: Currency
): TradeComparisonResult {
  if (!v2Trade && !v3Quote) {
    return { isV3Selected: false, bestV2Trade: null, bestV3Quote: null }
  }
  
  if (!v2Trade) {
    return { isV3Selected: true, bestV2Trade: null, bestV3Quote: v3Quote }
  }
  
  if (!v3Quote) {
    return { isV3Selected: false, bestV2Trade: v2Trade, bestV3Quote: null }
  }
  
  // Both trades exist - compare based on trade type
  if (tradeType === TradeType.EXACT_INPUT) {
    const v2Output = v2Trade.outputAmount
    const v3OutputAmount = CurrencyAmount.fromRawAmount(currencyOut, v3Quote.amountOut)
    
    if (v3OutputAmount.greaterThan(v2Output)) {
      return { isV3Selected: true, bestV2Trade: v2Trade, bestV3Quote: v3Quote }
    } else {
      return { isV3Selected: false, bestV2Trade: v2Trade, bestV3Quote: v3Quote }
    }
  } else {
    const v2Input = v2Trade.inputAmount
    const v3InputAmount = CurrencyAmount.fromRawAmount(currencyIn, v3Quote.amountIn)
    
    if (v3InputAmount.lessThan(v2Input)) {
      return { isV3Selected: true, bestV2Trade: v2Trade, bestV3Quote: v3Quote }
    } else {
      return { isV3Selected: false, bestV2Trade: v2Trade, bestV3Quote: v3Quote }
    }
  }
}

// Trade Object Creation
export function createTradeObject(
  comparison: TradeComparisonResult,
  tradeType: TradeType,
  currencyIn: Currency,
  currencyOut: Currency,
  gasEstimateUSD: string
) {
  const { isV3Selected, bestV2Trade, bestV3Quote } = comparison
  
  
  if (!isV3Selected && bestV2Trade) {
    // Create V2 ClassicTrade
    
    const routeParams = {
      v2Routes: [{ routev2: bestV2Trade.route, inputAmount: bestV2Trade.inputAmount, outputAmount: bestV2Trade.outputAmount }],
      v3Routes: [],
      mixedRoutes: [],
      tradeType,
    }
    
    const trade = new ClassicTrade(routeParams)
    
    // ClassicTrade constructor doesn't set routes properly, set manually
    if (!trade.routes || trade.routes.length === 0) {
      trade.routes = routeParams.v2Routes
    }
    
    
    const finalTrade = {
      ...trade,
      // Fix property names - UI expects inputAmount/outputAmount, not _inputAmount/_outputAmount
      inputAmount: bestV2Trade.inputAmount,
      outputAmount: bestV2Trade.outputAmount,
      // Fix routes - transaction handler expects v2Routes property
      v2Routes: routeParams.v2Routes,
      // Add executionPrice that trade validation expects
      executionPrice: bestV2Trade.executionPrice,
      // Add worstExecutionPrice method that trade validation expects
      worstExecutionPrice: function(slippageTolerance: any) {
        return bestV2Trade.worstExecutionPrice(slippageTolerance)
      },
      // Add missing methods required by analytics
      minimumAmountOut: function(slippageTolerance: any) {
        return bestV2Trade.minimumAmountOut(slippageTolerance)
      },
      maximumAmountIn: function(slippageTolerance: any) {
        return bestV2Trade.maximumAmountIn(slippageTolerance)
      },
      inputTax: bestV2Trade.inputTax || new Percent(0),
      outputTax: bestV2Trade.outputTax || new Percent(0),
      // Add priceImpact from V2Trade if available, otherwise calculate manually
      priceImpact: bestV2Trade.priceImpact || calculatePriceImpact(currencyIn, currencyOut, bestV2Trade.inputAmount, bestV2Trade.outputAmount),
      gasUseEstimate: 250000,
      gasUseEstimateUSD: gasEstimateUSD,
      quoteMethod: QuoteMethod.CLIENT_SIDE_FALLBACK,
      approveInfo: { needsApprove: false },
      routing: 'CLASSIC',
    }
    
    return finalTrade
  } else if (isV3Selected && bestV3Quote) {
    // Create custom V3 trade object
    
    const v3InputAmount = tradeType === TradeType.EXACT_INPUT ? 
      CurrencyAmount.fromRawAmount(currencyIn, bestV3Quote.amountIn) :
      CurrencyAmount.fromRawAmount(currencyIn, bestV3Quote.amountIn)
    
    const v3OutputAmount = tradeType === TradeType.EXACT_INPUT ?
      CurrencyAmount.fromRawAmount(currencyOut, bestV3Quote.amountOut) :
      CurrencyAmount.fromRawAmount(currencyOut, bestV3Quote.amountOut)
    
    // Create a proper Price object with baseCurrency and quoteCurrency
    const executionPrice = new Price(
      currencyIn,  // baseCurrency
      currencyOut, // quoteCurrency
      v3InputAmount.quotient.toString(),
      v3OutputAmount.quotient.toString()
    )
    
    const finalV3Trade = {
      tradeType,
      inputAmount: v3InputAmount,
      outputAmount: v3OutputAmount,
      executionPrice: executionPrice,
      // Add v3Routes property that transaction handler expects
      v3Routes: [{
        inputAmount: v3InputAmount,
        outputAmount: v3OutputAmount,
        path: [currencyIn, currencyOut], // Direct path for single-hop V3 trades
        pools: [{
          fee: bestV3Quote.fee,
          tickSpacing: bestV3Quote.tickSpacing,
          token0: currencyIn,
          token1: currencyOut
        }]
      }],
      gasUseEstimate: 250000,
      gasUseEstimateUSD: gasEstimateUSD,
      quoteMethod: QuoteMethod.CLIENT_SIDE_FALLBACK,
      approveInfo: { needsApprove: false },
      routing: 'CLASSIC',
      isV3: true, // Flag to identify V3 trades
      v3Quote: bestV3Quote, // Include the raw quote data
      // Add worstExecutionPrice method that trade validation expects
      worstExecutionPrice: function(slippageTolerance: any) {
        // Create a new Price object with slippage-adjusted amounts
        if (tradeType === TradeType.EXACT_INPUT) {
          // For exact input, worst price is lower output
          const slippageFactor = new Percent(1).subtract(slippageTolerance)
          const worstOutputAmount = v3OutputAmount.multiply(slippageFactor)
          return new Price(
            currencyIn,
            currencyOut,
            v3InputAmount.quotient.toString(),
            worstOutputAmount.quotient.toString()
          )
        } else {
          // For exact output, worst price is higher input
          const slippageFactor = new Percent(1).add(slippageTolerance)
          const worstInputAmount = v3InputAmount.multiply(slippageFactor)
          return new Price(
            currencyIn,
            currencyOut,
            worstInputAmount.quotient.toString(),
            v3OutputAmount.quotient.toString()
          )
        }
      },
      // Add missing methods required by analytics
      minimumAmountOut: function(slippageTolerance: any) {
        if (tradeType === TradeType.EXACT_INPUT) {
          // For exact input, minimum output is reduced by slippage
          const slippageFactor = new Percent(1).subtract(slippageTolerance)
          return v3OutputAmount.multiply(slippageFactor)
        } else {
          // For exact output, the output amount is already exact
          return v3OutputAmount
        }
      },
      maximumAmountIn: function(slippageTolerance: any) {
        if (tradeType === TradeType.EXACT_OUTPUT) {
          // For exact output, maximum input is increased by slippage
          const slippageFactor = new Percent(1).add(slippageTolerance)
          return v3InputAmount.multiply(slippageFactor)
        } else {
          // For exact input, the input amount is already exact
          return v3InputAmount
        }
      },
      inputTax: new Percent(0),
      outputTax: new Percent(0),
      // Add priceImpact calculation for V3 trade
      priceImpact: calculatePriceImpact(currencyIn, currencyOut, v3InputAmount, v3OutputAmount),
    } as any
    
    return finalV3Trade
  }
  
  return null
}